#define KELLY_DECOMP_SAVELOAD_VTABLE
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_SAVELOAD_VTABLE

class NamesMenu {
public:
    ~NamesMenu();
};

class KeyboardMenu {
public:
    ~KeyboardMenu();
};

class DialogMenu {
public:
    ~DialogMenu();
};

class MultiLineString {
public:
    ~MultiLineString();
};

class GenericGameSaver {
public:
    static GenericGameSaver *inst();
    void releaseIconData();
};

class SaveLoadFrontEnd : public FEMultiMenu {
    char data[0x32f0 - sizeof(FEMultiMenu)];
    MultiLineString *sftd;

public:
    NamesMenu *NameMenu;
    KeyboardMenu *KeyMenu;
    DialogMenu *dialogMenu;

    virtual ~SaveLoadFrontEnd();
};

SaveLoadFrontEnd::~SaveLoadFrontEnd()
{
    delete NameMenu;
    delete KeyMenu;
    delete dialogMenu;
    delete sftd;
#ifdef TARGET_PS2
    GenericGameSaver::inst()->releaseIconData();
#endif
}
